Looking at this ticket, I need to implement an authorization decision function using deny-overrides combining (XACML 3.0 C.2).

Key points:
1. Principal matching: `"*"` (any), `"user:<subject>"`, or `"role:<role>"` (exact matches, not patterns)
2. Action/Resource: Support trailing `*` for prefix matching only; other wildcards are literal
3. Deny-overrides: Any DENY match → DENY; else any ALLOW match → ALLOW; else default DENY
4. Validate entire request and all policies before deciding
5. Effect must be exactly "ALLOW" or "DENY" (case-sensitive)

Let me trace through the example from the ticket:
- Contractor with `role:contractor` → hits `role:contractor DENY` on `docs/reports/*` → DENY (even though `user:alice ALLOW` exists)
- This is correct: deny-overrides means the DENY wins regardless of position or specificity

```json
{
  "code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide access using deny-overrides policy combining.

    Args:
        request: Dict with 'subject', 'roles' (list), 'action', 'resource'.
        policies: List of dicts with 'effect', 'principal', 'action', 'resource'.

    Returns:
        "ALLOW" or "DENY".

    Raises:
        ValueError: If request or policies are invalid.
    """

    # Validate request
    if 'subject' not in request:
        raise ValueError("Request missing 'subject'")
    if 'roles' not in request:
        raise ValueError("Request missing 'roles'")
    if not isinstance(request['roles'], list):
        raise ValueError("Request 'roles' must be a list")
    if 'action' not in request:
        raise ValueError("Request missing 'action'")
    if 'resource' not in request:
        raise ValueError("Request missing 'resource'")

    subject = request['subject']
    roles = request['roles']
    action = request['action']
    resource = request['resource']

    # Validate all policies before deciding
    for policy in policies:
        if 'effect' not in policy:
            raise ValueError("Policy missing 'effect'")
        if 'principal' not in policy:
            raise ValueError("Policy missing 'principal'")
        if 'action' not in policy:
            raise ValueError("Policy missing 'action'")
        if 'resource' not in policy:
            raise ValueError("Policy missing 'resource'")

        effect = policy['effect']
        if effect not in ('ALLOW', 'DENY'):
            raise ValueError(f"Policy effect must be exactly 'ALLOW' or 'DENY', got: '{effect}'")

    # Deny-overrides combining: any DENY wins
    for policy in policies:
        if _policy_matches(policy, subject, roles, action, resource):
            if policy['effect'] == 'DENY':
                return 'DENY'

    # If no matching DENY, check for matching ALLOW
    for policy in policies:
        if _policy_matches(policy, subject, roles, action, resource):
            if policy['effect'] == 'ALLOW':
                return 'ALLOW'

    # Default deny
    return 'DENY'


def _policy_matches(policy: dict, subject: str, roles: list, action: str, resource: str) -> bool:
    """Check if a policy matches the given request."""
    principal = policy['principal']
    if not _principal_matches(principal, subject, roles):
        return False

    if not _pattern_matches(policy['action'], action):
        return False

    if not _pattern_matches(policy['resource'], resource):
        return False

    return True


def _principal_matches(principal: str, subject: str, roles: list) -> bool:
    """Check if a principal matches the request."""
    if principal == '*':
        return True

    if principal.startswith('user:'):
        user_part = principal[5:]
        return user_part == subject

    if principal.startswith('role:'):
        role_part = principal[5:]
        return role_part in roles

    return False


def _pattern_matches(pattern: str, value: str) -> bool:
    """Check if a pattern (with optional trailing *) matches a value."""
    if pattern.endswith('*'):
        prefix = pattern[:-1]
        return value.startswith(prefix)
    else:
        return pattern == value
